def load_stl_ascii_content(content, path):
    import re
    tris=[]
    pat=re.compile(r'facet\s+normal\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)\s+outer\s+loop\s+vertex\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)\s+vertex\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)\s+vertex\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)\s+([-\d\.eE+]+)', re.IGNORECASE|re.DOTALL)
    for m in pat.finditer(content):
        try:
            nx=float(m.group(1)); ny=float(m.group(2)); nz=float(m.group(3))
            v0=(float(m.group(4)), float(m.group(5)), float(m.group(6)))
            v1=(float(m.group(7)), float(m.group(8)), float(m.group(9)))
            v2=(float(m.group(10)), float(m.group(11)), float(m.group(12)))
            tris.append((v0,v1,v2,(nx,ny,nz),(255,255,0)))
        except:
            continue
    return tris

def load_stl(path):
    try:
        with open(path,'r') as f:
            content=f.read()
    except Exception:
        sys.stderr.write(f"thread 'main' (1) panicked at src/inputs.rs:126:39:\ncalled `Result::unwrap()` on an `Err` value: \"filename: [{path}] couldn't load, tobj couldnt load/parse OBJ. open file failed\"\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        sys.exit(101)

    # Check if contains facet
    if "facet" in content.lower():
        tris=load_stl_ascii_content(content, path)
        if not tris:
            sys.stderr.write(f"thread 'main' (1) panicked at src/inputs.rs:126:39:\ncalled `Result::unwrap()` on an `Err` value: \"filename: [{path}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer\"\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            sys.exit(101)
        return tris
    else:
        # binary
        try:
            with open(path,'rb') as f:
                header=f.read(80)
                tri_count=struct.unpack('<I', f.read(4))[0]
                tris=[]
                for _ in range(tri_count):
                    data=f.read(50)
                    if len(data)<50:
                        raise ValueError()
                    nx,ny,nz=struct.unpack('<fff', data[0:12])
                    v0=struct.unpack('<fff', data[12:24])
                    v1=struct.unpack('<fff', data[24:36])
                    v2=struct.unpack('<fff', data[36:48])
                    tris.append((v0,v1,v2,(nx,ny,nz),(255,255,0)))
                return tris
        except Exception:
            sys.stderr.write(f"thread 'main' (1) panicked at src/inputs.rs:126:39:\ncalled `Result::unwrap()` on an `Err` value: \"filename: [{path}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer\"\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            sys.exit(101)

def load_model(path):
    lower=path.lower()
    if lower.endswith(".stl"):
        return load_stl(path)
    else:
        # try obj, if it fails due to missing file, error already handled
        # If file contains "solid", maybe it's STL but named .obj? Try STL second?
        try:
            return load_obj(path)
        except SystemExit:
            raise
        except Exception as e:
            # try stl
            try:
                return load_stl(path)
            except SystemExit:
