                parts=line.split()
                if not parts: continue
                if parts[0]=="v":
                    try:
                        verts.append((float(parts[1]), float(parts[2]), float(parts[3])))
                    except:
                        continue
                elif parts[0]=="usemtl":
                    cur_mtl=parts[1]
                elif parts[0]=="f":
