def render_buffers(tris, width, height, rx, ry, rz):
    if not tris:
        char_buf=[[' ' for _ in range(width)] for _ in range(height)]
        color_buf=[[(0,0,0) for _ in range(width)] for _ in range(height)]
        return char_buf, color_buf

    all_verts=[]
    for v0,v1,v2,_,_ in tris:
        all_verts.extend([v0,v1,v2])
    min_x=min(v[0] for v in all_verts); max_x=max(v[0] for v in all_verts)
    min_y=min(v[1] for v in all_verts); max_y=max(v[1] for v in all_verts)
    min_z=min(v[2] for v in all_verts); max_z=max(v[2] for v in all_verts)
    cx=(min_x+max_x)/2; cy=(min_y+max_y)/2; cz=(min_z+max_z)/2
    extent=max(max_x-min_x, max_y-min_y, max_z-min_z)
    scale=2.0/extent if extent!=0 else 1.0

    # Adjust scale to match original's size: original seems to use larger scale
    # We will use scale * 1.0, but with aspect correction

    transformed=[]
    for v0,v1,v2,n,col in tris:
        def tr(v):
            v=(v[0]-cx, v[1]-cy, v[2]-cz)
            v=(v[0]*scale, v[1]*scale, v[2]*scale)
            v=apply_rot(v,rx,ry,rz)
            return (v[0], v[1], v[2]+2.0)  # tz=2.0 seems closer
        tv0=tr(v0); tv1=tr(v1); tv2=tr(v2)
        tn=apply_rot(n,rx,ry,rz)
        transformed.append((tv0,tv1,tv2,tn,col))

    projected=[]
    for v0,v1,v2,n,col in transformed:
        def proj(v):
            x,y,z=v
            if z<=0.1: z=0.1
            # Orthographic with perspective division
            # Use width and height for scaling, with aspect correction for terminal
            # Original aspect seemed ~0.8, let's use 1.0 for now
            xp = x / z * (width/2) + width/2
            yp = -y / z * (height/2) + height/2
            return (xp,yp,z)
        p0=proj(v0); p1=proj(v1); p2=proj(v2)
        projected.append((p0,p1,p2,n,col))

    char_buf=[[' ' for _ in range(width)] for _ in range(height)]
    color_buf=[[(0,0,0) for _ in range(width)] for _ in range(height)]
    depth_buf=[[float('inf') for _ in range(width)] for _ in range(height)]

    light_dir=normalize((0,0,-1))
    # For shading, use gradient, but for OBJ use fixed '#'
    # Determine if tris are from OBJ (have many colors) vs STL (yellow)
    # We will check if any color != yellow and != white -> OBJ
    is_obj = any(col != (255,255,0) and col != (255,255,255) and col != (1,1,1) for _,_,_,_,col in tris)
    # Actually test_model has many colors, so is_obj True
    # For OBJ, use fixed '#'
    # For STL, use gradient

    for p0,p1,p2,n,col in projected:
        if is_obj:
            char='#'
        else:
            intensity=dot(n, light_dir)
            intensity=max(0.0, min(1.0, intensity))
            idx=int(intensity*(len(GRADIENT)-1)+0.5)
            char=GRADIENT[idx]
            if char==' ':
                char='#'
        def edge(ax,ay,bx,by,cx,cy):
            return (cx-ax)*(by-ay) - (cy-ay)*(bx-ax)
        area=edge(p0[0],p0[1],p1[0],p1[1],p2[0],p2[1])
        if abs(area)<1e-6:
            continue
        min_px = max(0, int(math.floor(min(p0[0], p1[0], p2[0]))))
        max_px = min(width-1, int(math.ceil(max(p0[0], p1[0], p2[0]))))
        min_py = max(0, int(math.floor(min(p0[1], p1[1], p2[1]))))
        max_py = min(height-1, int(math.ceil(max(p0[1], p1[1], p2[1]))))
        for y in range(min_py, max_py+1):
            for x in range(min_px, max_px+1):
                w0=edge(p1[0],p1[1],p2[0],p2[1], x+0.5, y+0.5)
                w1=edge(p2[0],p2[1],p0[0],p0[1], x+0.5, y+0.5)
                w2=edge(p0[0],p0[1],p1[0],p1[1], x+0.5, y+0.5)
                if (w0>=0 and w1>=0 and w2>=0) or (w0<=0 and w1<=0 and w2<=0):
                    z=(p0[2]+p1[2]+p2[2])/3
                    if z < depth_buf[y][x]:
                        depth_buf[y][x]=z
                        char_buf[y][x]=char
                        color_buf[y][x]=col
    return char_buf, color_buf

