#!/usr/bin/env python3
import sys, os, math, struct, fcntl, termios, time, re

GRADIENT = " .:-=+*#%@"

def sub(a,b): return (a[0]-b[0], a[1]-b[1], a[2]-b[2])
def cross(a,b): return (a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0])
def dot(a,b): return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]
def normalize(v):
    l=math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2])
    return (v[0]/l, v[1]/l, v[2]/l) if l!=0 else (0,0,0)
def rotate_x(v,a):
    c=math.cos(a); s=math.sin(a)
    x,y,z=v
    return (x, y*c - z*s, y*s + z*c)
def rotate_y(v,a):
    c=math.cos(a); s=math.sin(a)
    x,y,z=v
    return (x*c + z*s, y, -x*s + z*c)
def rotate_z(v,a):
    c=math.cos(a); s=math.sin(a)
    x,y,z=v
    return (x*c - y*s, x*s + y*c, z)
def apply_rot(v,rx,ry,rz):
    v=rotate_x(v,rx)
    v=rotate_y(v,ry)
    v=rotate_z(v,rz)
    return v

def load_mtl(mtl_path):
    mats={}
    cur=None
    with open(mtl_path) as f:
        for line in f:
            line=line.strip()
            if not line or line.startswith("#"): continue
            parts=line.split()
            if parts[0]=="newmtl":
                cur=parts[1]
            elif parts[0]=="Kd" and cur:
                try:
                    r=float(parts[1]); g=float(parts[2]); b=float(parts[3])
                    mats[cur]=(int(r*255), int(g*255), int(b*255))
                except:
                    pass
    return mats

def load_obj(path):
    verts=[]
    tris=[]
    mtl_file=None
