            sys.exit(101)

def load_model(path):
    low=path.lower()
    if low.endswith(".stl"):
        return load_stl(path)
    else:
        try:
            return load_obj(path)
        except SystemExit:
            raise
        except:
            try:
                return load_stl(path)
            except SystemExit:
                raise
            except:
