                z_rot=parse_float_err(token.split("=",1)[1]); i+=1
            elif token.startswith("-"):
                sys.stderr.write(f"error: Found argument '{token}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFor more information try --help\n")
                sys.exit(1)
            else:
                inputs.append(token); i+=1

        if len(inputs)==0:
            sys.stderr.write("error: The following required arguments were not provided:\n    <input filename(s)>...\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFor more information try --help\n")
            sys.exit(1)

        files=inputs[0].split()
        all_tris=[]
        for fp in files:
            all_tris.extend(load_model(fp))

        try:
            fd=sys.stdout.fileno()
            winsz=fcntl.ioctl(fd, termios.TIOCGWINSZ, b'\x00'*8)
            rows, cols, _, _ = struct.unpack('HHHH', winsz)
            if rows==0 or cols==0:
                raise OSError()
        except Exception:
            sys.stderr.write("Error: IoError(Os { code: 25, kind: Uncategorized, message: \"Inappropriate ioctl for device\" })\n")
            sys.exit(1)

        use_color = not b_flag
        sys.stdout.write("\x1b[?25l")
        sys.stdout.flush()
        try:
            angle=0.0
            while True:
                cb, colb = render_buffers(all_tris, cols, rows, x_rot, y_rot+angle, z_rot)
                sys.stdout.write("\x1b[1;1H")
                if use_color:
                    out=""
                    for y in range(rows):
                        for x in range(cols):
                            c=cb[y][x]
                            col=colb[y][x]
                            if c==' ':
                                out+=f"\x1b[48;2;25;25;25m\x1b[38;2;0;0;0m \x1b[49m\x1b[39m"
                            else:
                                r,g,b=col
                                out+=f"\x1b[48;2;25;25;25m\x1b[38;2;{r};{g};{b}m{c}\x1b[49m\x1b[39m"
                        if y != rows-1:
                            out+="\n"
                    sys.stdout.write(out)
                else:
                    out=""
                    for y in range(rows):
                        for x in range(cols):
                            out+=cb[y][x]
                        out+="\n"
                    sys.stdout.write(out)
                sys.stdout.flush()
                angle+=0.1
                time.sleep(0.05)
        except KeyboardInterrupt:
            sys.stdout.write("\x1b[?25h")
            sys.exit(0)

if __name__=="__main__":
    main()
